actions.script:
def fmt = { v -> ec.l10n.format((v ?: 0) as BigDecimal, "#,##,##0") }
def confWord = { p -> p == null ? "Building up" : (p >= 75 ? "Strong" : (p >= 60 ? "Good" : (p >= 45 ? "Fair" : "Early estimate"))) }
def trendWord = { t -> t == "growing" ? "Going up" : (t == "softening" ? "Slowing down" : "Holding steady") }
def driverWord = { d ->
    if (!d) return "—"
    def up = d.toString().contains("rising")
    if (d.toString().contains("footfall")) return up ? "More customers coming in" : "Fewer customers coming in"
    return up ? "Customers spending more each visit" : "Customers spending a little less"
}
trendNice = trendWord(fc.trendLabel)
driverNice = driverWord(fc.primaryDriver)
confNice = confWord(fc.confidencePct)
hasData = (fc.confidencePct != null)
confColor = (fc.confidencePct != null && fc.confidencePct >= 60) ? "success" : (fc.confidencePct != null && fc.confidencePct >= 45 ? "warning" : "grey")
perDay = (fc.projectedNext7 != null) ? (fc.projectedNext7 / 7.0) : 0
// plain-words summary built from the numbers
if (hasData) {
    plain = "Over the next 7 days you're likely to sell about " + sym + fmt(fc.projectedNext7) +
        " — roughly " + sym + fmt(perDay) + " a day. Sales are " + trendNice.toLowerCase() +
        ", and " + (fc.peakDay ?: "the weekend") + " is usually your busiest day. " +
        "Expect around " + fmt(fc.next7Traffic) + " customers spending about " + sym + fmt(fc.next7Aov) + " each. " +
        "The main change right now: " + driverNice.toLowerCase() + ". " +
        "How sure are we? " + confNice + " — and this gets sharper every day as more sales come in."
} else {
    plain = "We need a couple of weeks of sales before we can predict reliably. Keep billing through the POS and check back soon."
}
catList.each { it.dirNice = trendWord(it.trend); it.relWord = confWord(it.confidencePct) }

// ZE-SALES-026 (SL-089): a single glance-able lead line (replaces the dense paragraph), and
// bar-chart prep for the product-group breakdown (biggest group first, proportional bar widths).
if (hasData) {
    leadLine = "You're on track to sell about " + sym + fmt(fc.projectedNext7) + " this week — sales are " +
        trendNice.toLowerCase() + ", and " + driverNice.substring(0,1).toLowerCase() + driverNice.substring(1) + "."
} else {
    leadLine = plain
}
catList = catList.sort { -((it.projectedNext7 ?: 0) as BigDecimal) }
def _maxCat = catList ? (catList.collect { (it.projectedNext7 ?: 0) as BigDecimal }.max()) : null
catList.each { c ->
    def v = (c.projectedNext7 ?: 0) as BigDecimal
    c.barPct = (_maxCat != null && _maxCat > 0) ? (v * 100 / _maxCat).setScale(1, java.math.RoundingMode.HALF_UP) : (0 as BigDecimal)
}
// Build the horizontal bar chart as raw HTML — Moqui containers put `style` into `class`, so a
// proportional-width bar needs real inline styles, which only render-mode HTML provides.
def _esc = { s -> (s ?: '').toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;') }
def _barColor = { t -> (t == 'growing') ? '#2e9e6a' : (t == 'softening' ? '#d9534f' : '#5c6bc0') }
def _b = new StringBuilder()
_b.append('<div style="font-size:0.9rem;">')
_b.append('<div style="display:flex;align-items:center;gap:12px;padding-bottom:6px;font-size:0.68rem;text-transform:uppercase;letter-spacing:.04em;color:#9a9aa8;font-weight:700;">')
_b.append('<div style="width:24%;">Group</div><div style="flex:1;">Share of next 7 days</div><div style="width:96px;text-align:right;">Next 7 days</div><div style="width:64px;text-align:right;">Per day</div><div style="width:118px;text-align:center;">Direction</div></div>')
catList.each { c ->
    _b.append('<div style="display:flex;align-items:center;gap:12px;padding:9px 0;border-bottom:1px solid rgba(128,128,128,0.14);">')
    _b.append('<div style="width:24%;font-weight:600;">' + _esc(c.category) + '</div>')
    _b.append('<div style="flex:1;background:rgba(128,128,140,0.16);border-radius:8px;height:15px;overflow:hidden;"><div style="width:' + (c.barPct ?: 0) + '%;min-width:2px;background:' + _barColor(c.trend) + ';height:15px;border-radius:8px;"></div></div>')
    _b.append('<div style="width:96px;text-align:right;font-weight:700;">' + sym + fmt(c.projectedNext7) + '</div>')
    _b.append('<div style="width:64px;text-align:right;color:#9a9aa8;">' + sym + fmt(c.perDay) + '</div>')
    _b.append('<div style="width:118px;text-align:center;color:#7a7a88;font-size:0.82rem;">' + _esc(c.dirNice) + '</div>')
    _b.append('</div>')
}
_b.append('</div>')
catChartHtml = _b.toString()
